"use client";

import { useRef } from "react";
import { motion, useInView } from "framer-motion";
import { Calendar, Clock, ArrowRight } from "lucide-react";
import Link from "next/link";
import { blogPosts } from "@/data/blog";

export function BlogSection() {
  const sectionRef = useRef<HTMLElement | null>(null);
  const isInView = useInView(sectionRef, { amount: 0.2, once: false });

  const sectionVariants = {
    hidden: { opacity: 0, y: 40 },
    visible: {
      opacity: 1,
      y: 0,
      transition: { duration: 0.9, delay: 0.15, ease: [0.215, 0.61, 0.355, 1] as const },
    },
  };

  // Get the latest post only
  const latestPost = blogPosts[0];

  return (
    <motion.section
      ref={sectionRef}
      id="blog"
      className="py-16 px-4 md:px-8 lg:px-16 flex items-center"
      variants={sectionVariants}
      initial="hidden"
      animate={isInView ? "visible" : "hidden"}
    >
      <div className="max-w-7xl mx-auto w-full">
        {/* Header */}
        <motion.div
          className="mb-10 text-center"
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: false }}
          transition={{ duration: 0.6 }}
        >
          <h2 className="text-4xl md:text-5xl font-bold mb-4 text-foreground">Latest from the Blog</h2>
          <p className="text-lg text-muted-foreground max-w-2xl mx-auto">
            I write about AI/ML concepts, tutorials, and things I'm learning along the way.
          </p>
        </motion.div>

        {/* Featured Blog Post - Smaller */}
        {latestPost && (
          <motion.article
            className="group relative overflow-hidden rounded-xl border border-border bg-card/80 backdrop-blur-sm hover:border-primary/50 hover:shadow-lg hover:-translate-y-1 transition-all duration-300 max-w-2xl mx-auto"
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: false }}
            transition={{ duration: 0.4 }}
          >
            <div className="p-6">
              {/* Category */}
              <div className="inline-block px-2.5 py-0.5 rounded-full bg-primary-light border border-border mb-3">
                <span className="text-xs font-medium text-primary">{latestPost.category}</span>
              </div>

              {/* Title */}
              <h3 className="text-xl font-bold text-foreground mb-2 group-hover:text-primary transition-colors">
                {latestPost.title}
              </h3>

              {/* Excerpt */}
              <p className="text-muted-foreground text-sm mb-4 leading-relaxed line-clamp-2">
                {latestPost.excerpt}
              </p>

              {/* Meta */}
              <div className="flex items-center gap-3 text-xs text-muted-foreground mb-4">
                <div className="flex items-center gap-1">
                  <Calendar className="w-3 h-3" />
                  {latestPost.date}
                </div>
                <div className="flex items-center gap-1">
                  <Clock className="w-3 h-3" />
                  {latestPost.readTime}
                </div>
              </div>

              {/* Read More */}
              <Link
                href={`/blog/${latestPost.slug}`}
                className="inline-flex items-center gap-1 text-sm font-medium text-primary hover:gap-2 transition-all"
              >
                Read Article
                <ArrowRight className="w-4 h-4" />
              </Link>
            </div>
          </motion.article>
        )}

        {/* Notes Section - No icon, with blue button */}
        <motion.div
          className="mt-12 max-w-2xl mx-auto"
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: false }}
          transition={{ duration: 0.5, delay: 0.2 }}
        >
          <div className="rounded-xl border border-border bg-card/80 backdrop-blur-sm p-6">
            <h3 className="text-lg font-bold text-foreground mb-3">Notes</h3>
            <p className="text-muted-foreground text-sm leading-relaxed mb-4">
              This section is where I'll share quick thoughts, learning notes, and insights from my journey in AI/ML.
              More notes will be added as my journey continues...
            </p>
            <Link
              href="/blog"
              className="inline-flex items-center gap-2 px-5 py-2.5 rounded-lg bg-[#708dcd] text-white text-sm font-medium hover:bg-[#5a75b3] transition-colors"
            >
              Go to Blog
              <ArrowRight className="w-4 h-4" />
            </Link>
          </div>
        </motion.div>
      </div>
    </motion.section>
  );
}
